#pragma once
#include <vector>
#include <cmath>
#include <cstdint>
#include <cstring>
inline std::vector<unsigned char> readBlob(const char*name){FILE*f=fopen(name,"rb");if(!f){fprintf(stderr,"missing fixture %s\n",name);exit(3);}fseek(f,0,SEEK_END);size_t bytes=ftell(f);rewind(f);std::vector<unsigned char>out(bytes);if(fread(out.data(),1,bytes,f)!=bytes)exit(3);fclose(f);return out;}
struct CheckedState{std::vector<double>values;bool ok=true;double absolute=0,relative=0;};
inline CheckedState checkState(const std::vector<float4>&pos,const std::vector<float4>&vel,const std::vector<float4>&rpos,const std::vector<float4>&rvel,const std::vector<unsigned>&keys,const std::vector<unsigned>&index,const std::vector<unsigned>&starts,const std::vector<unsigned>&ends,const std::vector<double>&cpu,const simParams_t&p){size_t N=pos.size();CheckedState c;std::vector<bool>seen(N,false);std::vector<unsigned>cs(p.numCells,0xffffffff),ce(p.numCells,0xffffffff);auto hashCPU=[&](float4 a){int x=int(floorf((a.x-p.worldOrigin.x)/p.cellSize.x)),y=int(floorf((a.y-p.worldOrigin.y)/p.cellSize.y)),z=int(floorf((a.z-p.worldOrigin.z)/p.cellSize.z));return unsigned(((z&63)*64+(y&63))*64+(x&63));};for(size_t i=0;i<N;i++){unsigned id=index[i];if(keys[i]>=p.numCells||id>=N||seen[id]){c.ok=false;continue;}seen[id]=true;c.ok&=keys[i]==hashCPU(pos[id]);if(i)c.ok&=keys[i-1]>=keys[i];if(i==0||keys[i]!=keys[i-1])cs[keys[i]]=i;if(i+1==N||keys[i]!=keys[i+1])ce[keys[i]]=i+1;}c.ok&=cs==starts;for(size_t i=0;i<cs.size();i++)if(cs[i]!=0xffffffff)c.ok&=ce[i]==ends[i];auto addFloat=[&](double got,double expected){double d=fabs(got-expected);c.absolute=std::max(c.absolute,d);c.relative=std::max(c.relative,d/std::max(fabs(expected),1e-5));c.ok&=std::isfinite(got)&&d<=1e-5;c.values.push_back(got);};for(size_t i=0;i<N;i++)for(int k=0;k<4;k++){float a;memcpy(&a,(char*)&pos[i]+4*k,4);addFloat(a,cpu[4*i+k]);}for(size_t i=0;i<N;i++)for(int k=0;k<4;k++){float a;memcpy(&a,(char*)&vel[i]+4*k,4);addFloat(a,cpu[4*N+4*i+k]);}for(auto x:keys)c.values.push_back(x);for(auto x:index)c.values.push_back(x);for(auto x:starts)c.values.push_back(x);for(size_t i=0;i<ends.size();i++)c.values.push_back(starts[i]==0xffffffff?double(0xffffffff):double(ends[i]));for(size_t i=0;i<N;i++)for(int k=0;k<4;k++){float a;memcpy(&a,(char*)&rpos[i]+4*k,4);addFloat(a,index[i]<N?cpu[4*index[i]+k]:0);}for(size_t i=0;i<N;i++)for(int k=0;k<4;k++){float a;memcpy(&a,(char*)&rvel[i]+4*k,4);addFloat(a,index[i]<N?cpu[8*N+4*index[i]+k]:0);}for(size_t i=0;i<N;i++){c.ok&=pos[i].w==1.f&&vel[i].w==0.f;for(float v:{pos[i].x,pos[i].y,pos[i].z})c.ok&=v>=-1.f+p.particleRadius-1e-5&&v<=1.f-p.particleRadius+1e-5;}return c;}
inline std::vector<double> parameterValues(const simParams_t&p){return {p.colliderPos.x,p.colliderPos.y,p.colliderPos.z,p.colliderRadius,p.gravity.x,p.gravity.y,p.gravity.z,p.globalDamping,p.particleRadius,double(p.gridSize.x),double(p.gridSize.y),double(p.gridSize.z),double(p.numCells),p.worldOrigin.x,p.worldOrigin.y,p.worldOrigin.z,p.cellSize.x,p.cellSize.y,p.cellSize.z,double(p.numBodies),double(p.maxParticlesPerCell),p.spring,p.damping,p.shear,p.attraction,p.boundaryDamping};}
